mapper.select:
SELECT B.BOARD_NO , B.BOARD_TYPE , CODE_NAME AS BOARD_TYPE_NAME , B.COMPANY_CODE , B.SUBJECT , B.CONTENTS , B.READ_COUNT , TO_CHAR(B.CREATE_DATE, 'YYYY-MM-DD') AS CREATE_DATE , B.CREATE_BY , B.PARENT_BOARD_NO FROM BOARD B INNER JOIN CODE_DTL CD ON B.COMPANY_CODE = CD.COMPANY_CODE AND B.BOARD_TYPE = CD.CODE AND CD.CATEGORY = 'BT' WHERE B.COMPANY_CODE = #{company_code}
AND (B.SUBJECT LIKE CONCAT('%', #{searchText}, '%') OR B.CONTENTS LIKE CONCAT('%', #{searchText}, '%') )
AND B.BOARD_TYPE = #{searchBoadrType}
ORDER BY B.BOARD_NO

SELECT COALESCE(MAX(BOARD_NO), 0) + 1
  FROM BOARD
 WHERE COMPANY_CODE = #{company_code}

mapper.insert:
INSERT INTO BOARD
( BOARD_NO
, BOARD_TYPE
, COMPANY_CODE
, SUBJECT
, CONTENTS
, READ_COUNT
, START_DATE
, END_DATE
, CREATE_DATE
, CREATE_BY
, UPDATE_DATE
, UPDATE_BY
, PARENT_BOARD_NO
, IN_OUT_FLAG
, MAIN_POPUP_YN)
VALUES 
( #{boardNo}
, #{boardType}
, #{company_code}
, #{subject}
, #{contents}
, 0
, #{startDate}
, #{endDate}
, NOW()
, #{update_by}
, NOW()
, #{update_by}
, #{parentBoardNo}
, 'I'
, #{mainPopupYn})

mapper.update:
UPDATE BOARD
   SET SUBJECT = #{subject}
     , BOARD_TYPE = #{boardType}
     , MAIN_POPUP_YN = #{mainPopupYn}
     , START_DATE = #{startDate}
     , END_DATE = #{endDate}
     , CONTENTS = #{contents}
     , UPDATE_BY = #{update_by}
     , UPDATE_DATE = NOW()
 WHERE COMPANY_CODE = #{company_code}
   AND BOARD_NO = #{boardNo}

mapper.insert:
INSERT INTO BOARD_FILE
(
  COMPANY_CODE
, BOARD_NO
, FILE_SEQ
, ORIGIN_FILE_NAME
, FILE_SIZE
, CONTENT_TYPE
, BOARD_FILE_FIELD
, CREATE_DATE
, CREATE_BY
)
VALUES
( #{companyCode}
, #{boardNo}
, (SELECT COALESCE(MAX(FILE_SEQ), 0) + 1
     FROM BOARD_FILE
    WHERE COMPANY_CODE = #{companyCode}
      AND BOARD_NO = #{boardNo})
, #{originFileName}
, #{fileSize}
, #{contentType}
, #{fileData, jdbcType=BINARY}
, NOW()
, #{createBy}
)

mapper.delete:
DELETE FROM BOARD_FILE
 WHERE COMPANY_CODE = #{companyCode}
   AND BOARD_NO     = #{boardNo}
   AND FILE_SEQ     = #{fileSeq}
